import re

def check_visual_labels_for_unsafe_text(labels):
    unsafe_patterns = [r'\b(adult|violence|gore|nudity)\b']
    for label in labels:
        if any(re.search(pattern, label['name'], re.IGNORECASE) for pattern in unsafe_patterns):
            return True
    return False

import boto3

def archive_image_analysis_artifacts(bucket_name, artifacts):
    s3 = boto3.client('s3')
    for key, value in artifacts.items():
        s3.put_object(Bucket=bucket_name, Key=key, Body=value)
